import { useState, useRef, useEffect, useCallback } from "react";

// ─── constants ────────────────────────────────────────────────────────────────
const C = {
  hilgenreiner: "#00e5ff",
  perkins_r:    "#ff6b35",
  perkins_l:    "#ffd166",
  femur_r:      "#ff6b35",
  femur_l:      "#ffd166",
};

const GROUPS = [
  { id:"hilgenreiner", label:"Hilgenreiner", color:C.hilgenreiner, slots:["Trirradiada D","Trirradiada E"] },
  { id:"perkins_r",    label:"Perkins D",    color:C.perkins_r,    slots:["Bordo acetab. D"] },
  { id:"perkins_l",    label:"Perkins E",    color:C.perkins_l,    slots:["Bordo acetab. E"] },
  { id:"femur_r",      label:"Fêmur D",      color:C.femur_r,      slots:["Medial D","Lateral D"] },
  { id:"femur_l",      label:"Fêmur E",      color:C.femur_l,      slots:["Medial E","Lateral E"] },
];

const STEP_IDS    = ["upload", ...GROUPS.map(g=>g.id), "result"];
const DOT_R       = 7;    // ← smaller dots (was 13)
const HIT_R_CSS   = 32;   // hit target stays large for easy touch
const DRAG_THRESH = 6;
const MAG_R       = 62;   // ← smaller magnifier (was 88)
const MAG_Z       = 4.0;
const ZOOM_STEP   = 0.35;
const ZOOM_MIN    = 1.0;
const ZOOM_MAX    = 8.0;
const LOGO_SRC = "data:image/png;base64,";
const BONE_LEARNING_LOGO = "data:image/svg+xml;base64,";

// ─── classification ───────────────────────────────────────────────────────────
function dst(a,b){ return Math.sqrt((a.x-b.x)**2+(a.y-b.y)**2); }

function calcReimers(pts){
  const {hilgenreiner:h, perkins_r:pr, perkins_l:pl, femur_r:fr, femur_l:fl} = pts;
  if(h.length<2 || !pr[0] || !pl[0] || fr.length<2 || fl.length<2) return null;

  const dx = h[1].x-h[0].x,  dy = h[1].y-h[0].y;
  const len = Math.sqrt(dx*dx+dy*dy);
  if(!len) return null;

  // Unit vector along Hilgenreiner
  const hu = {x:dx/len, y:dy/len};

  // Scalar projection onto the Hilgenreiner axis
  function projH(pt){ return pt.x*hu.x + pt.y*hu.y; }

  // ─── Reimers index — side-independent calculation ─────────────────────────
  //
  //  The user marks (in order):
  //    med  = medial  edge of femoral head  (1st click)
  //    lat  = lateral edge of femoral head  (2nd click)
  //    perk = acetabular edge (Perkins line tangent point)
  //
  //  All distances are projections along the Hilgenreiner direction.
  //
  //  B = |projH(lat) − projH(med)|        → total projected head width
  //
  //  The lateral tangent line sits at projH(lat).
  //  The Perkins line sits at projH(perk).
  //  The medial tangent line sits at projH(med).
  //
  //  The lateral edge is OUTSIDE the acetabulum when it is on the opposite
  //  side of Perkins from the medial edge.  We detect this automatically:
  //
  //    sign_lat_from_perk = sign(projH(lat) − projH(perk))
  //    sign_med_from_perk = sign(projH(med) − projH(perk))
  //
  //  If the signs differ, the head straddles Perkins.
  //  The overhang A = |projH(lat) − projH(perk)|, but only if lat is on the
  //  OUTSIDE (i.e. the same side as away-from-med relative to perk).
  //
  //  Simplest sign-agnostic formula that works for both hips:
  //
  //    A = max(0,  |projH(lat) − projH(perk)|  when lat is outside Perkins )
  //
  //  "lat is outside Perkins" means lat is further from med than perk is:
  //    i.e. |projH(lat)−projH(med)| > |projH(perk)−projH(med)|
  //    AND  projH(lat) and projH(perk) are on the same side of projH(med)... 
  //
  //  The cleanest approach: work in a coordinate system where med=0, lat=B>0.
  //  Project perk into that system:
  //    p_perk_local = projH(perk) − projH(med), scaled so that lat → B
  //    (i.e. just use the raw projH differences, since hu is a unit vector)
  //
  //  In local coords (med at 0, lat at B — always positive by construction):
  //    p_lat_local   = B  (always)
  //    p_perk_local  = projH(perk) − projH(med)
  //
  //  A = B − clamp(p_perk_local, 0, B)
  //    = how much of [perk…lat] lies outside the acetabulum
  //
  //  This formula is identical for both hips because we always orient the
  //  local axis from med toward lat.

  function calcSide(perk, med, lat){
    const P_med  = projH(med);
    const P_lat  = projH(lat);
    const P_perk = projH(perk);

    // B: total head width (always ≥ 0)
    const B = Math.abs(P_lat - P_med);

    // Orient local axis: med → lat direction
    // In local coords, med=0 and lat=B (positive).
    // Project perk into local coords:
    const P_perk_local = (P_lat >= P_med)
      ? (P_perk - P_med)      // lat is to the right of med
      : (P_med  - P_perk);    // lat is to the left  of med → flip axis

    // A = portion of head beyond Perkins (outside acetabulum)
    // perk_local inside [0,B] → A = B - perk_local
    // perk_local ≥ B          → entire head inside → A = 0
    // perk_local ≤ 0          → entire head outside → A = B
    const A = Math.max(0, Math.min(B, B - P_perk_local));

    const index = B > 0 ? Math.round(A / B * 1000) / 10 : 0;

    return {
      index,
      diam:   Math.round(B),
      beyond: Math.round(A),
      P_med, P_lat, P_perk,
    };
  }

  return {
    right: calcSide(pr[0], fr[0], fr[1]),
    left:  calcSide(pl[0], fl[0], fl[1]),
  };
}

// ─── Acetabular Index calculation ────────────────────────────────────────────
//
//  The acetabular index (AI) is the angle between:
//    - the Hilgenreiner line (H)
//    - the line from the triradiate cartilage (H point) to the acetabular edge (P point)
//
//  For the RIGHT hip:
//    H point = hilgenreiner[0]  (trirradiada D — 1st click)
//    P point = perkins_r[0]     (bordo acetabular D)
//
//  For the LEFT hip:
//    H point = hilgenreiner[1]  (trirradiada E — 2nd click)
//    P point = perkins_l[0]     (bordo acetabular E)
//
//  The angle is computed as:
//    vec_H = unit vector along Hilgenreiner (dx, dy)
//    vec_A = vector from H_point to P_point
//    angle = arctan( |component of vec_A perpendicular to H| / |component of vec_A along H| )
//          = arctan( |cross(vec_H, vec_A)| / dot(vec_H, vec_A) )
//  We take the absolute value and clamp to [0°, 90°].

function calcAcetabular(pts){
  const {hilgenreiner:h, perkins_r:pr, perkins_l:pl} = pts;
  if(h.length<2 || !pr[0] || !pl[0]) return null;

  const dx = h[1].x-h[0].x, dy = h[1].y-h[0].y;
  const len = Math.sqrt(dx*dx+dy*dy);
  if(!len) return null;

  const hu = {x:dx/len, y:dy/len}; // unit vector along Hilgenreiner

  function angleFor(hPt, pPt){
    // Vector from triradiate cartilage to acetabular edge
    const ax = pPt.x - hPt.x;
    const ay = pPt.y - hPt.y;
    const vLen = Math.sqrt(ax*ax+ay*ay);
    if(!vLen) return 0;
    // dot product with Hilgenreiner unit vector (= horizontal component)
    const dotH = ax*hu.x + ay*hu.y;
    // cross product magnitude (= vertical component, perpendicular to H)
    const crossH = Math.abs(ax*hu.y - ay*hu.x);
    // angle = atan2(perpendicular, horizontal)
    const angleDeg = Math.atan2(crossH, Math.abs(dotH)) * 180 / Math.PI;
    return Math.round(angleDeg * 10) / 10;
  }

  return {
    right: angleFor(h[0], pr[0]),  // triradiate D → perkins D
    left:  angleFor(h[1], pl[0]),  // triradiate E → perkins E
  };
}

function classifyAI(deg){
  if(deg<20) return {label:"Normal",      col:"#00e096"};
  if(deg<25) return {label:"Limítrofe",   col:"#ffd166"};
             return {label:"Aumentado",   col:"#ff4757"};
}

// Updated classification: <30 normal, 30-60 subluxado, >60 luxado
function classify(i){
  if(i<10)  return {label:"Normal",      col:"#00e096"};
  if(i<=30) return {label:"Displásico",  col:"#48cae4"};
  if(i<=60) return {label:"Subluxado",   col:"#ffd166"};
            return {label:"Luxado",      col:"#ff4757"};
}

// ─── App ──────────────────────────────────────────────────────────────────────
export default function App(){
  const canvasRef = useRef(null);
  const wrapRef   = useRef(null);
  const fileInputRef = useRef(null);

  // All mutable interaction state in one ref — event listeners always see current values
  const S = useRef({
    step:0,
    pts:{hilgenreiner:[],perkins_r:[],perkins_l:[],femur_r:[],femur_l:[]},
    imgEl:null, imgNatW:1, imgNatH:1,
    canvW:800, canvH:500,
    // view transform: zoom + pan (in canvas-pixel space)
    zoom:1.0, panX:0, panY:0,
    // pointer tracking
    down:false, downCSS:null, downImgPt:null, movedEnough:false,
    dragging:null,   // {gid,idx} | null
    panning:false,   // true when in pan-mode and dragging
    downPan:null,    // {panX,panY} at pointer-down, for pan dragging
    magPos:null,     // image-coord {ix,iy} | null
    mode:"annotate", // "annotate" | "pan"
  });

  const [imgEl,    setImgEl]    = useState(null);
  const [step,     setStep]     = useState(0);
  const [pts,      setPts]      = useState({hilgenreiner:[],perkins_r:[],perkins_l:[],femur_r:[],femur_l:[]});
  const [canvSize, setCanvSize] = useState({w:800,h:500});
  const [results,  setResults]  = useState(null);
  const [aiResults, setAiResults] = useState(null); // Acetabular Index
  const [zoom,     setZoom]     = useState(1.0);
  const [mode,     setMode]     = useState("annotate"); // "annotate"|"pan"
  const [exportImg, setExportImg] = useState(null); // data-URL for export preview modal

  // keep S in sync with React state
  useEffect(()=>{ S.current.step=step; },     [step]);
  useEffect(()=>{ S.current.pts=pts; },       [pts]);
  useEffect(()=>{ S.current.imgEl=imgEl; },   [imgEl]);
  useEffect(()=>{ S.current.canvW=canvSize.w; S.current.canvH=canvSize.h; },[canvSize]);
  useEffect(()=>{ S.current.zoom=zoom; },     [zoom]);
  useEffect(()=>{ S.current.mode=mode; },     [mode]);

  const isAnnotating = step>0 && step<STEP_IDS.length-1;
  const isResult     = step===STEP_IDS.length-1;
  const curGrpId     = STEP_IDS[step];
  const curGrp       = GROUPS.find(g=>g.id===curGrpId)||null;

  // ── image loading ─────────────────────────────────────────────
  function loadFile(file){
    if(!file) return;
    const rd=new FileReader();
    rd.onload=ev=>{
      const el=new Image();
      el.onload=()=>{
        S.current.imgEl=el;
        S.current.imgNatW=el.naturalWidth;
        S.current.imgNatH=el.naturalHeight;
        S.current.zoom=1; S.current.panX=0; S.current.panY=0;
        setImgEl(el); setZoom(1);
        S.current.step=1; setStep(1);
      };
      el.onerror=()=>alert("Erro ao carregar imagem.");
      el.src=ev.target.result;
    };
    rd.readAsDataURL(file);
  }

  // ── canvas sizing ─────────────────────────────────────────────
  // Canvas is fixed size (the "viewport"); zoom/pan are virtual transforms
  useEffect(()=>{
    if(!imgEl) return;
    function resize(){
      const wrap=wrapRef.current; if(!wrap) return;
      const maxW=wrap.clientWidth||320;
      const maxH=Math.min(window.innerHeight*0.52,560);
      // Fit image at zoom=1
      const ratio=Math.min(maxW/imgEl.naturalWidth, maxH/imgEl.naturalHeight);
      const w=Math.round(imgEl.naturalWidth*ratio);
      const h=Math.round(imgEl.naturalHeight*ratio);
      // Store base scale (zoom=1 means this ratio)
      S.current.baseScale=ratio;
      S.current.canvW=w; S.current.canvH=h;
      setCanvSize({w,h});
    }
    resize();
    window.addEventListener("resize",resize);
    return ()=>window.removeEventListener("resize",resize);
  },[imgEl]);

  // ── draw ──────────────────────────────────────────────────────
  const draw = useCallback(()=>{
    const cv=canvasRef.current;
    const {imgEl:img, pts:p, canvW:W, canvH:H, zoom:z, panX:px, panY:py, magPos}=S.current;
    if(!cv||!img) return;
    const ctx=cv.getContext("2d");
    ctx.clearRect(0,0,W,H);

    // ── apply zoom/pan transform ──
    // base: image fills canvas at zoom=1
    // at zoom z, image is z times larger, panned by (px,py) in canvas-px
    const bs=S.current.baseScale||1;
    ctx.save();
    ctx.translate(px, py);
    ctx.scale(z, z);
    ctx.drawImage(img, 0, 0, img.naturalWidth*bs, img.naturalHeight*bs);
    ctx.fillStyle="rgba(0,8,20,0.10)";
    ctx.fillRect(0,0,img.naturalWidth*bs,img.naturalHeight*bs);
    ctx.restore();

    // All annotation points are stored in "base image coords" (zoom=1, no pan)
    // Convert to canvas px: cx = pt.x * bs * z + px
    function toCv(pt){ return {cx:pt.x*bs*z+px, cy:pt.y*bs*z+py}; }
    const sc=bs; // base scale

    // ── Hilgenreiner (infinite line only — dots drawn after AI lines) ──
    if(p.hilgenreiner.length===2){
      const a=toCv(p.hilgenreiner[0]), b=toCv(p.hilgenreiner[1]);
      infLine(ctx,a.cx,a.cy,b.cx,b.cy,C.hilgenreiner,W,H);
    }

    // ── Perkins (infinite lines only — dots drawn after AI lines) ──
    function drawPerkinsLine(arr,col){
      if(!arr.length||p.hilgenreiner.length<2) return;
      const ang=Math.atan2(p.hilgenreiner[1].y-p.hilgenreiner[0].y,
                           p.hilgenreiner[1].x-p.hilgenreiner[0].x)+Math.PI/2;
      arr.forEach(pt=>{ const c=toCv(pt); infLineAng(ctx,c.cx,c.cy,ang,col,W,H); });
    }
    drawPerkinsLine(p.perkins_r,C.perkins_r);
    drawPerkinsLine(p.perkins_l,C.perkins_l);

    // ── Acetabular Index lines (dashed) — drawn BEFORE any dots ──
    function drawAILine(hPt, pPt, col){
      if(!hPt||!pPt) return;
      const a=toCv(hPt), b=toCv(pPt);
      ctx.save();
      ctx.beginPath();
      ctx.strokeStyle=col; ctx.lineWidth=2;
      ctx.setLineDash([6,4]);
      ctx.shadowColor=col; ctx.shadowBlur=5;
      ctx.moveTo(a.cx,a.cy); ctx.lineTo(b.cx,b.cy);
      ctx.stroke(); ctx.restore();
    }
    if(p.hilgenreiner.length===2){
      drawAILine(p.hilgenreiner[0], p.perkins_r[0], C.perkins_r);
      drawAILine(p.hilgenreiner[1], p.perkins_l[0], C.perkins_l);
    }

    // ── Hilgenreiner dots (on top of AI lines) ──
    p.hilgenreiner.forEach((pt,i)=>{ const c=toCv(pt); dot(ctx,c.cx,c.cy,C.hilgenreiner,i===0?"TD":"TE"); });

    // ── Perkins dots (on top of AI lines) ──
    function drawPerkins(arr,col){
      if(!arr.length||p.hilgenreiner.length<2) return;
      arr.forEach(pt=>{ const c=toCv(pt); dot(ctx,c.cx,c.cy,col,"P"); });
    }
    drawPerkins(p.perkins_r,C.perkins_r);
    drawPerkins(p.perkins_l,C.perkins_l);

    // ── Femur ──
    // Hilgenreiner angle and perpendicular (Perkins direction)
    const hAngle = p.hilgenreiner.length===2
      ? Math.atan2(p.hilgenreiner[1].y-p.hilgenreiner[0].y,
                   p.hilgenreiner[1].x-p.hilgenreiner[0].x)
      : 0;
    const perpAng = hAngle + Math.PI/2;
    const huCv = {x:Math.cos(hAngle),  y:Math.sin(hAngle)};   // along Hilgenreiner
    const pvCv = {x:Math.cos(perpAng), y:Math.sin(perpAng)};  // perpendicular (Perkins dir)

    // Scalar projection of a canvas point onto the Hilgenreiner direction
    function projHcv(c){ return c.cx*huCv.x + c.cy*huCv.y; }


    // Draw femur: tangent lines parallel to Perkins through medial and lateral points,
    // plus a measurement bar parallel to Hilgenreiner connecting the two tangents.
    // arr[0] = medial point (first click), arr[1] = lateral point (second click).
    // This matches calcReimers exactly — no auto-detection of sides.
    function drawFemur(arr, col){
      if(arr.length>=2 && p.hilgenreiner.length===2){
        const cMed = toCv(arr[0]);   // medial  (first  click)
        const cLat = toCv(arr[1]);   // lateral (second click)

        // ── Tangent lines through each point, parallel to Perkins ──
        infLineAng(ctx, cMed.cx, cMed.cy, perpAng, col+"77", W, H);
        infLineAng(ctx, cLat.cx, cLat.cy, perpAng, col+"77", W, H);

        // ── Measurement bar parallel to Hilgenreiner ──
        // Place it at the average perp-coordinate (roughly at the equator of both points).
        // A point's "perp-coordinate" = projection onto the perp direction pvCv.
        // A canvas point with hu-projection h and perp-coordinate L is:
        //   x = h*huCv.x + L*pvCv.x,  y = h*huCv.y + L*pvCv.y
        const perpCoord = c => c.cx*pvCv.x + c.cy*pvCv.y;
        const L = (perpCoord(cMed) + perpCoord(cLat)) / 2;

        const fMed = { x: projHcv(cMed)*huCv.x + L*pvCv.x,
                       y: projHcv(cMed)*huCv.y + L*pvCv.y };
        const fLat = { x: projHcv(cLat)*huCv.x + L*pvCv.x,
                       y: projHcv(cLat)*huCv.y + L*pvCv.y };

        ctx.save();
        ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.setLineDash([]);
        // Bar
        ctx.beginPath(); ctx.moveTo(fMed.x,fMed.y); ctx.lineTo(fLat.x,fLat.y); ctx.stroke();
        // Tick marks perpendicular to bar at each end
        const tk = 7;
        [fMed, fLat].forEach(f=>{
          ctx.beginPath();
          ctx.moveTo(f.x - pvCv.x*tk, f.y - pvCv.y*tk);
          ctx.lineTo(f.x + pvCv.x*tk, f.y + pvCv.y*tk);
          ctx.stroke();
        });
        ctx.restore();
      }
      // Dots: arr[0]=M (medial), arr[1]=L (lateral), matching user instruction
      if(arr[0]){ const c=toCv(arr[0]); dot(ctx,c.cx,c.cy,col,"M"); }
      if(arr[1]){ const c=toCv(arr[1]); dot(ctx,c.cx,c.cy,col,"L"); }
    }
    drawFemur(p.femur_r, C.femur_r);
    drawFemur(p.femur_l, C.femur_l);

    // ── Magnifier ──
    if(magPos) drawMag(ctx,magPos,img,W,H,bs);
  },[]);

  useEffect(()=>{ draw(); },[draw,pts,canvSize,zoom,imgEl]);

  // ── draw helpers ──────────────────────────────────────────────
  function infLine(ctx,x1,y1,x2,y2,col,W,H){
    const dx=x2-x1,dy=y2-y1; if(!dx&&!dy) return;
    const ts=[-x1/dx,(W-x1)/dx,-y1/dy,(H-y1)/dy].filter(t=>isFinite(t)&&!isNaN(t));
    const cs=ts.map(t=>({x:x1+t*dx,y:y1+t*dy})).filter(q=>q.x>=-2&&q.x<=W+2&&q.y>=-2&&q.y<=H+2);
    if(cs.length<2) return;
    ctx.save(); ctx.beginPath();
    ctx.strokeStyle=col; ctx.lineWidth=1.5; ctx.shadowColor=col; ctx.shadowBlur=6;
    ctx.moveTo(cs[0].x,cs[0].y); ctx.lineTo(cs[cs.length-1].x,cs[cs.length-1].y);
    ctx.stroke(); ctx.restore();
  }
  function infLineAng(ctx,px,py,ang,col,W,H){
    const n=9999,dx=Math.cos(ang)*n,dy=Math.sin(ang)*n;
    infLine(ctx,px-dx,py-dy,px+dx,py+dy,col,W,H);
  }
  function dot(ctx,x,y,col,lbl=""){
    ctx.save();
    // outer ring
    ctx.beginPath(); ctx.arc(x,y,DOT_R+4,0,Math.PI*2);
    ctx.strokeStyle=col+"30"; ctx.lineWidth=2; ctx.stroke();
    // filled circle
    ctx.beginPath(); ctx.arc(x,y,DOT_R,0,Math.PI*2);
    ctx.fillStyle=col; ctx.shadowColor=col; ctx.shadowBlur=10; ctx.fill(); ctx.shadowBlur=0;
    // label
    if(lbl){
      ctx.fillStyle="#000"; ctx.font="bold "+(DOT_R)+"px monospace";
      ctx.textAlign="center"; ctx.textBaseline="middle"; ctx.fillText(lbl,x,y);
    }
    ctx.restore();
  }
  function drawMag(ctx,{ix,iy},img,W,H,bs){
    const r=MAG_R, z=MAG_Z;
    // Fixed top-right corner position
    const mx=W-r-12, my=r+12;
    // Source region in image natural coords
    const natX=ix - r/(z*bs), natY=iy - r/(z*bs), natS=(r*2)/(z*bs);
    ctx.save();
    ctx.shadowColor="rgba(0,0,0,0.85)"; ctx.shadowBlur=18;
    ctx.beginPath(); ctx.arc(mx,my,r+5,0,Math.PI*2);
    ctx.fillStyle="#050d14"; ctx.fill(); ctx.shadowBlur=0;
    ctx.beginPath(); ctx.arc(mx,my,r,0,Math.PI*2); ctx.clip();
    ctx.drawImage(img, natX,natY,natS,natS, mx-r,my-r,r*2,r*2);
    ctx.restore();
    // crosshair
    ctx.save(); ctx.strokeStyle="rgba(255,255,255,0.7)"; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(mx-12,my); ctx.lineTo(mx+12,my); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(mx,my-12); ctx.lineTo(mx,my+12); ctx.stroke();
    ctx.restore();
    // border
    ctx.beginPath(); ctx.arc(mx,my,r,0,Math.PI*2);
    ctx.strokeStyle="rgba(0,229,255,0.9)"; ctx.lineWidth=2; ctx.stroke();
    // zoom label
    ctx.fillStyle="rgba(0,229,255,0.6)";
    ctx.font="bold 8px monospace"; ctx.textAlign="center"; ctx.textBaseline="top";
    ctx.fillText(z+"×",mx,my+r+4);
  }

  // ── coordinate transforms ─────────────────────────────────────
  // CSS click → image natural coords (accounting for zoom+pan)
  function clientToImg(cssX,cssY){
    const cv=canvasRef.current; if(!cv) return {x:0,y:0};
    const rect=cv.getBoundingClientRect();
    const {canvW:W,canvH:H,zoom:z,panX:px,panY:py,baseScale:bs=1}=S.current;
    // canvas pixel
    const cpx=(cssX-rect.left)*(W/rect.width);
    const cpy=(cssY-rect.top)*(H/rect.height);
    // image natural coord
    return { x:(cpx-px)/(z*bs), y:(cpy-py)/(z*bs) };
  }
  function clientToCanvPx(cssX,cssY){
    const cv=canvasRef.current; if(!cv) return {cpx:0,cpy:0};
    const rect=cv.getBoundingClientRect();
    const {canvW:W,canvH:H}=S.current;
    return { cpx:(cssX-rect.left)*(W/rect.width), cpy:(cssY-rect.top)*(H/rect.height) };
  }

  // Hit-test: returns {gid,idx} or null
  function hitTest(cssX,cssY){
    const cv=canvasRef.current; if(!cv) return null;
    const rect=cv.getBoundingClientRect();
    const {pts:p,canvW:W,canvH:H,zoom:z,panX:px,panY:py,baseScale:bs=1}=S.current;
    const cpx=(cssX-rect.left)*(W/rect.width);
    const cpy=(cssY-rect.top)*(H/rect.height);
    const hitR=HIT_R_CSS*(W/rect.width);
    let best=null, bestD=hitR;
    for(const g of GROUPS){
      (p[g.id]||[]).forEach((pt,i)=>{
        const cx=pt.x*bs*z+px, cy=pt.y*bs*z+py;
        const dd=dst({x:cx,y:cy},{x:cpx,y:cpy});
        if(dd<bestD){ bestD=dd; best={gid:g.id,idx:i}; }
      });
    }
    return best;
  }

  // ── zoom helpers ──────────────────────────────────────────────
  function applyZoom(newZ,cssX,cssY){
    const cv=canvasRef.current;
    const cz=S.current.zoom;
    newZ=Math.max(ZOOM_MIN,Math.min(ZOOM_MAX,newZ));
    let {cpx,cpy}=clientToCanvPx(cssX??S.current.canvW/2, cssY??S.current.canvH/2);
    // zoom toward pointer: pan adjusts so the image point under cursor stays fixed
    const {panX:px,panY:py}=S.current;
    const newPanX=cpx-(cpx-px)*(newZ/cz);
    const newPanY=cpy-(cpy-py)*(newZ/cz);
    S.current.zoom=newZ; S.current.panX=newPanX; S.current.panY=newPanY;
    setZoom(newZ); draw();
  }
  function zoomIn()  { applyZoom(S.current.zoom+ZOOM_STEP); }
  function zoomOut() { applyZoom(S.current.zoom-ZOOM_STEP); }
  function zoomReset(){ S.current.zoom=1; S.current.panX=0; S.current.panY=0; setZoom(1); draw(); }

  // ── pointer events ────────────────────────────────────────────
  useEffect(()=>{
    const cv=canvasRef.current; if(!cv) return;

    function getCSS(e){
      if(e.touches&&e.touches.length) return {x:e.touches[0].clientX,y:e.touches[0].clientY};
      return {x:e.clientX,y:e.clientY};
    }
    function getCSSUp(e){
      if(e.changedTouches&&e.changedTouches.length)
        return {x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY};
      return {x:e.clientX,y:e.clientY};
    }

    // ── Pinch-to-zoom state ──────────────────────────────────────
    // Dedicated touchstart handler (no pinch — zoom via buttons only)
    function onTouchStart(e){
      if(S.current.step===0) return;
      e.preventDefault();
      e.stopPropagation();
      // Ignore multi-finger touches
      if(e.touches.length!==1) return;
      const isPan = S.current.mode==="pan";
      const t=e.touches[0];
      const css={x:t.clientX,y:t.clientY};
      const imgPt=clientToImg(css.x,css.y);
      const hit=hitTest(css.x,css.y);
      S.current.down=true;
      S.current.downCSS=css;
      S.current.downImgPt=imgPt;
      S.current.movedEnough=false;
      S.current.dragging=isPan?null:(hit||null);
      S.current.panning=false;
      S.current.downPan={panX:S.current.panX,panY:S.current.panY};
      S.current.magPos=isPan?null:{ix:imgPt.x,iy:imgPt.y};
      draw();
    }

    function onDown(e){
      // Mouse only (touch handled by onTouchStart)
      if(e.touches) return;
      if(S.current.step===0) return;
      e.preventDefault();
      e.stopPropagation();
      const isPan = S.current.mode==="pan";
      const css={x:e.clientX,y:e.clientY};
      const imgPt=clientToImg(css.x,css.y);
      const hit=hitTest(css.x,css.y);
      S.current.down=true;
      S.current.downCSS=css;
      S.current.downImgPt=imgPt;
      S.current.movedEnough=false;
      S.current.dragging=isPan?null:(hit||null);
      S.current.panning=false;
      S.current.downPan={panX:S.current.panX,panY:S.current.panY};
      S.current.magPos=isPan?null:{ix:imgPt.x,iy:imgPt.y};
      draw();
    }

    function onMove(e){
      if(S.current.step===0) return;
      e.preventDefault();
      e.stopPropagation();

      const isPan = S.current.mode==="pan";

      // Multi-finger touches: ignore (zoom is button-only)
      if(e.touches&&e.touches.length>1) return;

      if(!S.current.down) return;

      const css = e.touches
        ? {x:e.touches[0].clientX, y:e.touches[0].clientY}
        : {x:e.clientX, y:e.clientY};
      const imgPt=clientToImg(css.x,css.y);

      if(!S.current.movedEnough && S.current.downCSS){
        if(dst(css,S.current.downCSS)>DRAG_THRESH) S.current.movedEnough=true;
      }

      if(!isPan) S.current.magPos={ix:imgPt.x,iy:imgPt.y};

      if(S.current.movedEnough){
        if(S.current.dragging && !isPan){
          const {gid,idx}=S.current.dragging;
          setPts(prev=>{
            const arr=[...prev[gid]]; arr[idx]={x:imgPt.x,y:imgPt.y};
            const next={...prev,[gid]:arr}; S.current.pts=next; return next;
          });
        } else if(isPan && !S.current.dragging){
          const {cpx:cx0,cpy:cy0}=clientToCanvPx(S.current.downCSS.x,S.current.downCSS.y);
          const {cpx:cx1,cpy:cy1}=clientToCanvPx(css.x,css.y);
          S.current.panX=S.current.downPan.panX+(cx1-cx0);
          S.current.panY=S.current.downPan.panY+(cy1-cy0);
        }
      }
      draw();
    }

    function onUp(e){
      e.preventDefault(); e.stopPropagation();
      if(!S.current.down) return;
      S.current.down=false;
      const css=getCSSUp(e);
      const imgPt=clientToImg(css.x,css.y);
      const {dragging,movedEnough,step:st,pts:p,mode:m}=S.current;
      S.current.magPos=null;

      // TAP: no significant movement AND not dragging existing point AND in annotate mode
      const isTap=!movedEnough && !dragging && m==="annotate";

      if(isTap && st>0 && st<STEP_IDS.length-1){
        const gid=STEP_IDS[st];
        const grp=GROUPS.find(g=>g.id===gid);
        const cur=p[gid]||[];
        if(cur.length<grp.slots.length){
          const next=[...cur,{x:imgPt.x,y:imgPt.y}];
          const complete=next.length>=grp.slots.length;
          const updated={...p,[gid]:next}; S.current.pts=updated;
          setPts(()=>updated);
          if(complete){
            setTimeout(()=>{ const ns=st+1; S.current.step=ns; setStep(ns); },180);
          }
        }
      }

      S.current.dragging=null; S.current.movedEnough=false; S.current.downCSS=null;
      draw();
    }

    // Mouse wheel zoom — only in pan mode
    function onWheel(e){
      if(S.current.step===0||S.current.mode!=="pan") return;
      e.preventDefault();
      const delta=e.deltaY>0?-ZOOM_STEP:ZOOM_STEP;
      applyZoom(S.current.zoom+delta, e.clientX, e.clientY);
    }

    const opts={passive:false};
    cv.addEventListener("mousedown",   onDown,      opts);
    cv.addEventListener("mousemove",   onMove,      opts);
    cv.addEventListener("mouseup",     onUp,        opts);
    cv.addEventListener("mouseleave",  onUp,        opts);
    cv.addEventListener("touchstart",  onTouchStart,opts);
    cv.addEventListener("touchmove",   onMove,      opts);
    cv.addEventListener("touchend",    onUp,        opts);
    cv.addEventListener("touchcancel", onUp,        opts);
    cv.addEventListener("wheel",       onWheel,     opts);
    return ()=>{
      cv.removeEventListener("mousedown",   onDown);
      cv.removeEventListener("mousemove",   onMove);
      cv.removeEventListener("mouseup",     onUp);
      cv.removeEventListener("mouseleave",  onUp);
      cv.removeEventListener("touchstart",  onTouchStart);
      cv.removeEventListener("touchmove",   onMove);
      cv.removeEventListener("touchend",    onUp);
      cv.removeEventListener("touchcancel", onUp);
      cv.removeEventListener("wheel",       onWheel);
    };
  },[canvSize,zoom,mode]);

  // ── recalculate results ───────────────────────────────────────
  useEffect(()=>{
    if(isResult){
      const r=calcReimers(pts);
      S.current.lastResults=r;
      setResults(r);
      setAiResults(calcAcetabular(pts));
    }
  },[isResult,pts]);

  // ── UI helpers ────────────────────────────────────────────────
  function stepInstruction(){
    if(!curGrp) return "";
    const cur=pts[curGrpId]||[];
    const rem=curGrp.slots.slice(cur.length);
    if(!rem.length) return "✓ Completo — arraste para corrigir";
    return "Toque: "+rem[0];
  }
  function handleUndo(){
    const cur=pts[curGrpId]||[];
    if(cur.length>0){
      setPts(p=>{ const u={...p,[curGrpId]:[]}; S.current.pts=u; return u; });
    } else if(step>1){
      const prevId=STEP_IDS[step-1];
      setPts(p=>{ const u={...p,[prevId]:[]}; S.current.pts=u; return u; });
      const ns=step-1; S.current.step=ns; setStep(ns);
    }
  }
  function handleReset(){
    const e={hilgenreiner:[],perkins_r:[],perkins_l:[],femur_r:[],femur_l:[]};
    Object.assign(S.current,{step:0,pts:e,imgEl:null,dragging:null,magPos:null,down:false,zoom:1,panX:0,panY:0,mode:"annotate"});
    setPts(e); setStep(0); setImgEl(null); setResults(null); setAiResults(null); setZoom(1); setMode("annotate"); setExportImg(null);
  }

  function handleExport(){
    const {imgEl:img,pts:p,canvW:W,canvH:H,baseScale:bs=1}=S.current;
    if(!img) return;

    const res  = S.current.lastResults;
    const aiR  = calcAcetabular(p);

    // ── helpers ───────────────────────────────────────────────────────────────
    const SC=2;  // render at 2× for sharpness

    // Panel below the radiograph — fixed height
    const PANEL_H = 110;
    const TOTAL_H = H + PANEL_H;

    const ec=document.createElement("canvas");
    ec.width=W*SC; ec.height=TOTAL_H*SC;
    const ctx=ec.getContext("2d");
    ctx.scale(SC,SC);

    // ── Radiograph area ───────────────────────────────────────────────────────
    ctx.drawImage(img,0,0,W,H);
    ctx.fillStyle="rgba(0,8,20,0.10)"; ctx.fillRect(0,0,W,H);

    const sc=bs;
    function toCv(pt){ return {cx:pt.x*sc,cy:pt.y*sc}; }

    function infLine(x1,y1,x2,y2,col){
      const dx=x2-x1,dy=y2-y1; if(!dx&&!dy) return;
      const ts=[-x1/dx,(W-x1)/dx,-y1/dy,(H-y1)/dy].filter(t=>isFinite(t)&&!isNaN(t));
      const cs=ts.map(t=>({x:x1+t*dx,y:y1+t*dy})).filter(q=>q.x>=-2&&q.x<=W+2&&q.y>=-2&&q.y<=H+2);
      if(cs.length<2) return;
      ctx.save(); ctx.beginPath();
      ctx.strokeStyle=col; ctx.lineWidth=1.5; ctx.shadowColor=col; ctx.shadowBlur=5;
      ctx.moveTo(cs[0].x,cs[0].y); ctx.lineTo(cs[cs.length-1].x,cs[cs.length-1].y);
      ctx.stroke(); ctx.restore();
    }
    function infLineAng(px,py,ang,col){
      const n=9999; infLine(px-Math.cos(ang)*n,py-Math.sin(ang)*n,px+Math.cos(ang)*n,py+Math.sin(ang)*n,col);
    }
    function dot(x,y,col,lbl=""){
      ctx.save();
      ctx.beginPath(); ctx.arc(x,y,11,0,Math.PI*2);
      ctx.strokeStyle=col+"30"; ctx.lineWidth=2; ctx.stroke();
      ctx.beginPath(); ctx.arc(x,y,7,0,Math.PI*2);
      ctx.fillStyle=col; ctx.shadowColor=col; ctx.shadowBlur=10; ctx.fill(); ctx.shadowBlur=0;
      if(lbl){ ctx.fillStyle="#000"; ctx.font="bold 7px monospace"; ctx.textAlign="center"; ctx.textBaseline="middle"; ctx.fillText(lbl,x,y); }
      ctx.restore();
    }

    // Hilgenreiner line
    if(p.hilgenreiner.length===2){
      const[a,b]=[toCv(p.hilgenreiner[0]),toCv(p.hilgenreiner[1])];
      infLine(a.cx,a.cy,b.cx,b.cy,C.hilgenreiner);
    }
    // Perkins lines
    function drawPerkinsLineExp(arr,col){
      if(!arr.length||p.hilgenreiner.length<2) return;
      const ang=Math.atan2(p.hilgenreiner[1].y-p.hilgenreiner[0].y,p.hilgenreiner[1].x-p.hilgenreiner[0].x)+Math.PI/2;
      arr.forEach(pt=>{ const c=toCv(pt); infLineAng(c.cx,c.cy,ang,col); });
    }
    drawPerkinsLineExp(p.perkins_r,C.perkins_r); drawPerkinsLineExp(p.perkins_l,C.perkins_l);
    // AI dashed lines (before dots)
    if(p.hilgenreiner.length===2){
      function drawAIExp(hPt,pPt,col){
        if(!hPt||!pPt) return;
        const a=toCv(hPt),b=toCv(pPt);
        ctx.save(); ctx.beginPath();
        ctx.strokeStyle=col; ctx.lineWidth=2; ctx.setLineDash([6,4]);
        ctx.shadowColor=col; ctx.shadowBlur=4;
        ctx.moveTo(a.cx,a.cy); ctx.lineTo(b.cx,b.cy);
        ctx.stroke(); ctx.restore();
      }
      drawAIExp(p.hilgenreiner[0],p.perkins_r[0],C.perkins_r);
      drawAIExp(p.hilgenreiner[1],p.perkins_l[0],C.perkins_l);
    }
    // Hilgenreiner dots
    p.hilgenreiner.forEach((pt,i)=>{ const c=toCv(pt); dot(c.cx,c.cy,C.hilgenreiner,i===0?"TD":"TE"); });
    // Perkins dots
    function drawPerkins(arr,col){
      if(!arr.length||p.hilgenreiner.length<2) return;
      arr.forEach(pt=>{ const c=toCv(pt); dot(c.cx,c.cy,col,"P"); });
    }
    drawPerkins(p.perkins_r,C.perkins_r); drawPerkins(p.perkins_l,C.perkins_l);
    // Femur
    const hAngle=p.hilgenreiner.length===2?Math.atan2(p.hilgenreiner[1].y-p.hilgenreiner[0].y,p.hilgenreiner[1].x-p.hilgenreiner[0].x):0;
    const perpAng=hAngle+Math.PI/2;
    const huCv={x:Math.cos(hAngle),y:Math.sin(hAngle)};
    const pvCv={x:Math.cos(perpAng),y:Math.sin(perpAng)};
    function projHcv(c){ return c.cx*huCv.x+c.cy*huCv.y; }
    function drawFemur(arr,col){
      if(arr.length>=2&&p.hilgenreiner.length===2){
        const cMed=toCv(arr[0]),cLat=toCv(arr[1]);
        infLineAng(cMed.cx,cMed.cy,perpAng,col+"77");
        infLineAng(cLat.cx,cLat.cy,perpAng,col+"77");
        const perpCoord=c=>c.cx*pvCv.x+c.cy*pvCv.y;
        const L=(perpCoord(cMed)+perpCoord(cLat))/2;
        const fMed={x:projHcv(cMed)*huCv.x+L*pvCv.x,y:projHcv(cMed)*huCv.y+L*pvCv.y};
        const fLat={x:projHcv(cLat)*huCv.x+L*pvCv.x,y:projHcv(cLat)*huCv.y+L*pvCv.y};
        ctx.save(); ctx.strokeStyle=col; ctx.lineWidth=2; ctx.setLineDash([]);
        ctx.beginPath(); ctx.moveTo(fMed.x,fMed.y); ctx.lineTo(fLat.x,fLat.y); ctx.stroke();
        const tk=7;
        [fMed,fLat].forEach(f=>{ ctx.beginPath(); ctx.moveTo(f.x-pvCv.x*tk,f.y-pvCv.y*tk); ctx.lineTo(f.x+pvCv.x*tk,f.y+pvCv.y*tk); ctx.stroke(); });
        ctx.restore();
      }
      if(arr[0]){ const c=toCv(arr[0]); dot(c.cx,c.cy,col,"M"); }
      if(arr[1]){ const c=toCv(arr[1]); dot(c.cx,c.cy,col,"L"); }
    }
    drawFemur(p.femur_r,C.femur_r); drawFemur(p.femur_l,C.femur_l);

    // ── Separator line ────────────────────────────────────────────────────────
    ctx.save();
    ctx.strokeStyle="#1a3a5a"; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(0,H); ctx.lineTo(W,H); ctx.stroke();
    ctx.restore();

    // ── Results panel below radiograph ────────────────────────────────────────
    // Dark background for the panel
    ctx.fillStyle="#070d14"; ctx.fillRect(0,H,W,PANEL_H);

    function clsOf(i){ return i<10?{l:"Normal",c:"#00e096"}:i<=30?{l:"Displásico",c:"#48cae4"}:i<=60?{l:"Subluxado",c:"#ffd166"}:{l:"Luxado",c:"#ff4757"}; }
    function clsAI(d){ return d<20?{l:"Normal",c:"#00e096"}:d<25?{l:"Limítrofe",c:"#ffd166"}:{l:"Aumentado",c:"#ff4757"}; }

    // Layout: 4 columns (Reimers D | Reimers E | IA D | IA E)
    // Each column: W/4 wide
    const cols=4, colW=W/cols;
    const py0=H+8; // top padding inside panel

    const items=[
      { title:"REIMERS D", col:C.perkins_r,
        val: res?.right ? res.right.index+"%"  : "–",
        lbl: res?.right ? clsOf(res.right.index).l : "", clr: res?.right ? clsOf(res.right.index).c : "#555" },
      { title:"REIMERS E", col:C.perkins_l,
        val: res?.left  ? res.left.index+"%"   : "–",
        lbl: res?.left  ? clsOf(res.left.index).l  : "", clr: res?.left  ? clsOf(res.left.index).c  : "#555" },
      { title:"IA D",      col:C.perkins_r,
        val: aiR?.right!=null ? aiR.right+"°" : "–",
        lbl: aiR?.right!=null ? clsAI(aiR.right).l : "", clr: aiR?.right!=null ? clsAI(aiR.right).c : "#555" },
      { title:"IA E",      col:C.perkins_l,
        val: aiR?.left!=null  ? aiR.left+"°"  : "–",
        lbl: aiR?.left!=null  ? clsAI(aiR.left).l  : "", clr: aiR?.left!=null  ? clsAI(aiR.left).c  : "#555" },
    ];

    items.forEach((it,i)=>{
      const x0=i*colW;
      ctx.save();

      // top color accent bar
      ctx.fillStyle=it.col;
      ctx.fillRect(x0+6, H+2, colW-12, 3);

      // title
      ctx.fillStyle=it.col;
      ctx.font="bold 8px monospace"; ctx.textAlign="center";
      ctx.fillText(it.title, x0+colW/2, py0+14);

      // value — auto-fit font size so it never overflows the column
      const maxValW = colW - 10;
      let valSize = 22;
      ctx.font="bold "+valSize+"px monospace";
      while(ctx.measureText(it.val).width > maxValW && valSize > 10) valSize--;
      ctx.font="bold "+valSize+"px monospace";
      ctx.fillStyle=it.clr;
      ctx.textAlign="center";
      ctx.shadowColor=it.clr; ctx.shadowBlur=6;
      ctx.fillText(it.val, x0+colW/2, py0+46);
      ctx.shadowBlur=0;

      // classification label — also auto-fit
      let lblSize = 9;
      ctx.font=lblSize+"px monospace";
      while(ctx.measureText(it.lbl).width > maxValW && lblSize > 7) lblSize--;
      ctx.font=lblSize+"px monospace";
      ctx.fillStyle=it.clr;
      ctx.textAlign="center";
      ctx.fillText(it.lbl, x0+colW/2, py0+62);

      // vertical separator (except last)
      if(i<3){
        ctx.strokeStyle="#1a3a5a"; ctx.lineWidth=1;
        ctx.beginPath(); ctx.moveTo((i+1)*colW,H+6); ctx.lineTo((i+1)*colW,H+PANEL_H-6); ctx.stroke();
      }
      ctx.restore();
    });

    // ── Get data URL & export ─────────────────────────────────────────────────
    const dataUrl=ec.toDataURL("image/png");

    // Desktop: auto-download
    try {
      ec.toBlob(blob=>{
        if(!blob){ setExportImg(dataUrl); return; }
        const url=URL.createObjectURL(blob);
        const a=document.createElement("a");
        a.href=url; a.download="reimers_index.png";
        document.body.appendChild(a); a.click();
        setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); },1000);
      },"image/png");
    } catch(e){ /* fallback */ }

    // Always show modal (iOS: long-press to save; desktop: already downloaded)
    setExportImg(dataUrl);
  }

  const canZoomOut = zoom>ZOOM_MIN+0.01;
  const canZoomIn  = zoom<ZOOM_MAX-0.01;

  // ── render ────────────────────────────────────────────────────
  return (
    <div style={{minHeight:"100vh",background:"#070d14",color:"#c8d8e8",
      fontFamily:"'JetBrains Mono','Courier New',monospace",
      display:"flex",flexDirection:"column",overflow:"hidden"}}>

      {/* header */}
      <header style={{borderBottom:"1px solid #1a2a3a",padding:"10px 14px",flexShrink:0,
        display:"flex",alignItems:"center",gap:10,flexWrap:"wrap",
        background:"linear-gradient(90deg,#0a1520,#0d1e30)"}}>
        <img src={LOGO_SRC} alt="pelve"
          style={{width:44,height:44,borderRadius:8,flexShrink:0,
            objectFit:"cover",
            filter:"brightness(1.1) drop-shadow(0 0 6px #00e5ff55)",
            border:"1px solid #00e5ff33",background:"#000"}}/>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontSize:17,fontWeight:700,letterSpacing:2,color:"#e0f0ff",lineHeight:1.2}}>ÍNDICE DE REIMERS</div>
          <div style={{fontSize:11,color:"#7ab0c8",letterSpacing:1,marginTop:2}}>PERCENTUAL DE MIGRAÇÃO DO FÊMUR PROXIMAL</div>
        </div>
        {step>0 && <Btn col="#6a9aba" onClick={handleReset}>↺</Btn>}
      </header>

      {/* step bar */}
      {step>0 && (
        <div style={{display:"flex",overflowX:"auto",borderBottom:"1px solid #1a2a3a",
          background:"#08111a",padding:"0 4px",flexShrink:0,
          scrollbarWidth:"none",WebkitOverflowScrolling:"touch"}}>
          {GROUPS.map((g,i)=>{
            const si=i+1,done=step>si,active=step===si;
            return(
              <div key={g.id} style={{padding:"5px 8px",fontSize:12,letterSpacing:1,
                whiteSpace:"nowrap",display:"flex",alignItems:"center",gap:4,flexShrink:0,
                borderBottom:active?"2px solid "+g.color:done?"2px solid "+g.color+"55":"2px solid transparent",
                color:active?g.color:done?"#7aaabb":"#5a7a8a"}}>
                <span style={{width:13,height:13,borderRadius:"50%",display:"flex",
                  alignItems:"center",justifyContent:"center",fontSize:11,flexShrink:0,
                  background:done?g.color+"22":active?g.color+"33":"transparent",
                  border:"1px solid "+(done||active?g.color+"55":"#1a3a5a")}}>
                  {done?"✓":si}
                </span>
                {g.label.toUpperCase()}
              </div>
            );
          })}
        </div>
      )}

      <main style={{flex:1,overflowY:"auto",padding:10,
        display:"flex",flexDirection:"column",gap:8,
        WebkitOverflowScrolling:"touch"}}>

        {/* upload */}
        {step===0 && (
          <div style={{flex:1,display:"flex",flexDirection:"column",
            alignItems:"center",justifyContent:"center",gap:16,paddingTop:20}}>
            <div style={{textAlign:"center",maxWidth:320,display:"flex",flexDirection:"column",alignItems:"center",gap:10}}>
              <div style={{width:160,height:160,display:"flex",alignItems:"center",justifyContent:"center",mixBlendMode:"screen",filter:"drop-shadow(0 0 12px rgba(0,229,255,0.35))"}}>
                <img src={LOGO_SRC} alt="pelve"
                  style={{width:160,height:160,objectFit:"contain",mixBlendMode:"screen"}}/>
              </div>
              <h2 style={{fontSize:15,fontWeight:700,color:"#e0f0ff",margin:0,letterSpacing:1}}>
                Carregar Radiografia
              </h2>
              <p style={{fontSize:13,color:"#8abccc",lineHeight:1.7,margin:0}}>
                Selecione uma radiografia de bacia AP para medir o índice de migração de Reimers.
              </p>
            </div>
            <div
              onClick={()=>fileInputRef.current?.click()}
              onDragOver={e=>e.preventDefault()}
              onDrop={e=>{e.preventDefault();loadFile(e.dataTransfer.files[0]);}}
              style={{width:220,height:130,border:"2px dashed #1a3a5a",borderRadius:12,
                display:"flex",flexDirection:"column",alignItems:"center",
                justifyContent:"center",gap:6,cursor:"pointer",
                background:"linear-gradient(135deg,#0a1520,#0d1e30)"}}>
              <div style={{fontSize:24}}>📁</div>
              <div style={{fontSize:14,fontWeight:600,color:"#c0d8e8"}}>Toque ou arraste</div>
              <div style={{fontSize:12,color:"#7a9aaa"}}>JPG · PNG · HEIC</div>
            </div>
            <input ref={fileInputRef} type="file" accept="image/*"
              style={{display:"none"}}
              onChange={e=>{if(e.target.files[0])loadFile(e.target.files[0]);e.target.value="";}}/>
            {/* Bone Learning logo */}
            <div style={{marginTop:8,opacity:0.6}}>
              <img src={BONE_LEARNING_LOGO} alt="Bone Learning"
                style={{width:70,height:"auto",objectFit:"contain",
                  filter:"drop-shadow(0 0 4px rgba(0,229,255,0.15))"}}/>
            </div>
          </div>
        )}

        {/* annotation + result */}
        {(isAnnotating||isResult) && (
          <div style={{display:"flex",flexDirection:"column",gap:8}}>

            {/* instruction bar */}
            {isAnnotating && (
              <div style={{background:"#0a1a2a",border:"1px solid #1a3a5a",
                borderLeft:"3px solid "+(curGrp?.color||"#00e5ff"),
                borderRadius:7,padding:"7px 10px",fontSize:13,
                display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}>
                <div style={{minWidth:0,flex:1}}>
                  <span style={{fontWeight:700,color:"#e0f0ff"}}>{curGrp?.label.toUpperCase()}</span>
                  <span style={{color:"#7aaabb",margin:"0 5px"}}>→</span>
                  <span style={{color:"#a0c0d8"}}>{stepInstruction()}</span>
                </div>
                {(pts[curGrpId]?.length||0)>=(curGrp?.slots.length||0) && (
                  <Btn col="#00e5ff" onClick={()=>{const ns=step+1;S.current.step=ns;setStep(ns);}}>
                    Próximo →
                  </Btn>
                )}
              </div>
            )}

            {isResult && (
              <div style={{background:"#0a1a2a",border:"1px solid #1a3a5a",
                borderLeft:"3px solid #00e5ff",borderRadius:7,
                padding:"6px 10px",fontSize:12,color:"#9ac8d8"}}>
                💡 Arraste qualquer ponto para reposicionar — resultado recalcula automaticamente
              </div>
            )}

            {/* zoom + mode toolbar */}
            <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
              {/* mode toggle */}
              <div style={{display:"flex",background:"#0a1520",border:"1px solid #1a3a5a",
                borderRadius:6,overflow:"hidden",flexShrink:0}}>
                <ModeBtn active={mode==="annotate"} onClick={()=>{setMode("annotate");S.current.mode="annotate";}}>
                  ✏️ Anotar
                </ModeBtn>
                <ModeBtn active={mode==="pan"} onClick={()=>{setMode("pan");S.current.mode="pan";}}>
                  ✋ Mover
                </ModeBtn>
              </div>
              {/* zoom controls */}
              <div style={{display:"flex",background:"#0a1520",border:"1px solid #1a3a5a",
                borderRadius:6,overflow:"hidden",flexShrink:0}}>
                <IconBtn onClick={zoomOut} disabled={!canZoomOut} title="Zoom −">−</IconBtn>
                <div style={{padding:"5px 8px",fontSize:12,color:"#9ac8d8",
                  borderLeft:"1px solid #1a2a3a",borderRight:"1px solid #1a2a3a",
                  display:"flex",alignItems:"center",minWidth:36,justifyContent:"center",
                  fontVariantNumeric:"tabular-nums"}}>
                  {Math.round(zoom*100)}%
                </div>
                <IconBtn onClick={zoomIn} disabled={!canZoomIn} title="Zoom +">+</IconBtn>
              </div>
              <Btn col="#4a7090" onClick={zoomReset}>⌂ Reset</Btn>
              {isAnnotating && (
                <Btn col="#ff9f1c" onClick={handleUndo}>↩ Desfazer</Btn>
              )}
              <div style={{fontSize:12,color:"#7a9aaa",marginLeft:"auto"}}>
                {mode==="pan"?"Arraste para mover a imagem":"Toque p/ anotar · Arraste pontos"}
              </div>
            </div>

            {/* canvas */}
            <div ref={wrapRef} style={{borderRadius:9,overflow:"hidden",
              border:"1px solid #1a3a5a",background:"#000",flexShrink:0,
              touchAction:"none",userSelect:"none",
              WebkitUserSelect:"none",WebkitTapHighlightColor:"transparent"}}>
              <canvas ref={canvasRef}
                width={canvSize.w} height={canvSize.h}
                style={{display:"block",width:"100%",height:"auto",
                  touchAction:"none",WebkitTapHighlightColor:"transparent",
                  cursor: mode==="pan"?"grab":isAnnotating?"crosshair":"default"}}/>
            </div>


            {/* results */}
            {isResult && results && (
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                <div style={{fontSize:11,color:"#7ab0c8",letterSpacing:2}}>
                  ÍNDICE DE REIMERS
                </div>
                <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                  {[{side:"DIREITO",key:"right",col:C.perkins_r},
                    {side:"ESQUERDO",key:"left",col:C.perkins_l}].map(({side,key,col})=>{
                    const r=results[key]; if(!r) return null;
                    const cls=classify(r.index);
                    return(
                      <div key={key} style={{flex:"1 1 140px",
                        background:"linear-gradient(135deg,#0a1520,#0d1e30)",
                        border:"1px solid "+col+"33",borderTop:"3px solid "+col,
                        borderRadius:9,padding:12}}>
                        <div style={{fontSize:11,letterSpacing:2,color:col,marginBottom:3}}>FÊMUR {side}</div>
                        <div style={{fontSize:40,fontWeight:700,color:cls.col,lineHeight:1,marginBottom:2}}>
                          {r.index}<span style={{fontSize:13,fontWeight:400,color:"#8ab0c0"}}>%</span>
                        </div>
                        <div style={{fontSize:10,color:cls.col,marginBottom:8}}>{cls.label}</div>
                        <div style={{height:5,background:"#1a2a3a",borderRadius:3,marginBottom:6,overflow:"hidden"}}>
                          <div style={{height:"100%",width:Math.min(100,r.index)+"%",
                            background:"linear-gradient(90deg,#00e096,#ffd166,#ff4757)",
                            borderRadius:3,transition:"width 0.8s ease"}}/>
                        </div>

                      </div>
                    );
                  })}
                </div>
                {/* legend */}
                <div style={{background:"#08111a",border:"1px solid #1a2a3a",
                  borderRadius:7,padding:"8px 10px",display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
                  {[{r:"< 10%",  l:"Normal",     c:"#00e096"},
                    {r:"10–30%", l:"Displásico", c:"#48cae4"},
                    {r:"30–60%", l:"Subluxado",  c:"#ffd166"},
                    {r:"> 60%",  l:"Luxado",     c:"#ff4757"}].map(x=>(
                    <div key={x.r} style={{display:"flex",alignItems:"center",gap:4}}>
                      <div style={{width:7,height:7,borderRadius:"50%",background:x.c,flexShrink:0}}/>
                      <span style={{fontSize:12,color:"#9ab8c8"}}>{x.r}</span>
                      <span style={{fontSize:12,color:x.c}}>{x.l}</span>
                    </div>
                  ))}
                </div>
                {/* ── Acetabular Index ── */}
                {aiResults && (
                  <div style={{display:"flex",flexDirection:"column",gap:8}}>
                    <div style={{fontSize:11,color:"#7ab0c8",letterSpacing:2,marginTop:4}}>
                      ÍNDICE ACETABULAR
                    </div>
                    <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                      {[{side:"DIREITO",key:"right",col:C.perkins_r},
                        {side:"ESQUERDO",key:"left",col:C.perkins_l}].map(({side,key,col})=>{
                        const deg=aiResults[key]; if(deg==null) return null;
                        const cls=classifyAI(deg);
                        return(
                          <div key={key} style={{flex:"1 1 130px",
                            background:"linear-gradient(135deg,#0a1520,#0d1e30)",
                            border:"1px solid "+col+"33",borderTop:"3px solid "+col,
                            borderRadius:9,padding:"10px 12px"}}>
                            <div style={{fontSize:11,letterSpacing:2,color:col,marginBottom:3}}>
                              {side}
                            </div>
                            <div style={{fontSize:36,fontWeight:700,color:cls.col,lineHeight:1,marginBottom:2}}>
                              {deg}<span style={{fontSize:13,fontWeight:400,color:"#7ab0c8"}}>°</span>
                            </div>
                            <div style={{fontSize:11,color:cls.col,marginBottom:6}}>{cls.label}</div>
                            <div style={{height:4,background:"#1a2a3a",borderRadius:3,overflow:"hidden"}}>
                              <div style={{height:"100%",width:Math.min(100,deg/45*100)+"%",
                                background:"linear-gradient(90deg,#00e096,#ffd166,#ff4757)",
                                borderRadius:3,transition:"width 0.8s ease"}}/>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                    {/* AI legend */}
                    <div style={{background:"#08111a",border:"1px solid #1a2a3a",
                      borderRadius:7,padding:"8px 10px",display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
                      {[{r:"< 20°",  l:"Normal",    c:"#00e096"},
                        {r:"20–25°", l:"Limítrofe", c:"#ffd166"},
                        {r:"> 25°",  l:"Aumentado", c:"#ff4757"}].map(x=>(
                        <div key={x.r} style={{display:"flex",alignItems:"center",gap:4}}>
                          <div style={{width:7,height:7,borderRadius:"50%",background:x.c,flexShrink:0}}/>
                          <span style={{fontSize:12,color:"#9ab8c8"}}>{x.r}</span>
                          <span style={{fontSize:12,color:x.c}}>{x.l}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                <Btn col="#4a9aba" onClick={handleExport}>⬇ Exportar imagem</Btn>
                <Btn col="#00e5ff" onClick={handleReset}>↺ Nova medição</Btn>
              </div>
            )}
          </div>
        )}
      </main>

      {/* ── Export modal ── */}
      {exportImg && (
        <div onClick={()=>setExportImg(null)}
          style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.92)",
            display:"flex",flexDirection:"column",alignItems:"center",
            justifyContent:"center",gap:14,zIndex:9999,padding:16}}>
          <div style={{fontSize:12,color:"#00e5ff",letterSpacing:1,textAlign:"center"}}>
            📥 iOS: pressione e segure a imagem para salvar
            <br/>
            <span style={{color:"#7ab0c0",fontSize:11}}>Toque fora para fechar</span>
          </div>
          <img src={exportImg} alt="export"
            style={{maxWidth:"100%",maxHeight:"80vh",borderRadius:8,
              border:"1px solid #1a3a5a",boxShadow:"0 0 40px rgba(0,229,255,0.15)"}}/>
        </div>
      )}
    </div>
  );
}


// ─── small UI components ──────────────────────────────────────────────────────
function Btn({col,onClick,children}){
  return(
    <button onClick={onClick}
      style={{background:col+"18",border:"1px solid "+col+"55",
        color:col,borderRadius:5,padding:"6px 11px",fontSize:13,
        letterSpacing:0.8,cursor:"pointer",fontFamily:"inherit",
        WebkitTapHighlightColor:"transparent",flexShrink:0,whiteSpace:"nowrap"}}>
      {children}
    </button>
  );
}
function ModeBtn({active,onClick,children}){
  return(
    <button onClick={onClick}
      style={{padding:"6px 10px",fontSize:13,cursor:"pointer",
        fontFamily:"inherit",letterSpacing:0.5,border:"none",
        background:active?"#00e5ff22":"transparent",
        color:active?"#00e5ff":"#4a7090",
        WebkitTapHighlightColor:"transparent",whiteSpace:"nowrap",
        borderRight:"1px solid #1a2a3a"}}>
      {children}
    </button>
  );
}
function IconBtn({onClick,disabled,children,title}){
  return(
    <button onClick={disabled?undefined:onClick} title={title}
      style={{width:30,height:28,display:"flex",alignItems:"center",justifyContent:"center",
        fontSize:16,fontWeight:700,cursor:disabled?"default":"pointer",
        background:"transparent",border:"none",
        color:disabled?"#3a5a6a":"#9ac8d8",
        fontFamily:"inherit",
        WebkitTapHighlightColor:"transparent"}}>
      {children}
    </button>
  );
}
